import{_ as a}from"./chunks/740a2a134a781a41a166.BAa3HQQA.js";import{_ as o,C as l,o as i,c as r,j as e,a as n,E as s,a6 as u}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"价值方程式：如何快速成为顶尖1%的人","description":"","frontmatter":{"title":"价值方程式：如何快速成为顶尖1%的人","originalTitle":"The Value Equation: How To Become A Top 1% Individual Fast","date":"2024-03-09","originalUrl":"https://thedankoe.com/letters/the-value-equation-how-to-become-a-top-1-individual-fast/","minutes":10,"sourceHash":"dddb9ba59ccf55c11d560f9e92aa02580db27cacc16289c3c1ad33956bc19f40","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-value-equation-how-to-become-a-top-1-individual-fast/"}]]},"headers":[],"relativePath":"letters/the-value-equation-how-to-become-a-top-1-individual-fast.md","filePath":"letters/the-value-equation-how-to-become-a-top-1-individual-fast.md"}'),c={name:"letters/the-value-equation-how-to-become-a-top-1-individual-fast.md"};function h(d,p,m,g,f,b){const t=l("ArticleMeta");return i(),r("div",null,[p[0]||(p[0]=e("h1",{id:"价值方程式-如何快速成为顶尖1-的人",tabindex:"-1"},[n("价值方程式：如何快速成为顶尖1%的人 "),e("a",{class:"header-anchor",href:"#价值方程式-如何快速成为顶尖1-的人","aria-label":'Permalink to "价值方程式：如何快速成为顶尖1%的人"'},"​")],-1)),s(t),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/JI3ajrxdLEk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+a+'" alt=""></p><p>你在追逐地位。</p><p>这是人性中一条从人类诞生之初就存在的不变法则。</p><p>认为自己不是在追逐地位、而是在追求某种高尚事业，这本身仍然是一种地位游戏。想要杀死自我的欲望，仍然是自我的欲望。这并不意味着它是坏事。它意味着这是自然的，一旦你接受这一点，你就会开始因此而获得回报。</p><p>不管你喜不喜欢，人们都会根据你的相对地位来评判你。不接受这一点，就等于接受另一个选项：过一种被不公平对待、对世界几乎没有影响力的人生。</p><p>你在自己的社交圈里有地位。</p><p>你在工作或职业中有地位。</p><p>你在宗教组织中有地位。</p><p>人们第一次见到你时，就会给你分配一个地位。这不由你控制，但你可以通过定位自己来增加被视为高地位的可能性。</p><p>人们是否愿意与你互动、给你机会，取决于那个地位。</p><p>人们是否愿意雇用你、付钱给你、或帮助你，取决于那个地位。</p><p>即便这并非有意为之——鉴于他们极高的觉知水平，我怀疑这确实是有意的——那些我们所歌颂的领袖，比如耶稣基督（Jesus Christ）、埃克哈特·托利（Eckhart Tolle）、纳瓦尔·拉维坎特（Naval Ravikant）、艾伦·瓦茨（Alan Watts）、乔丹·彼得森（Jordan Peterson）、肯·威尔伯（Ken Wilber），以及其他大多数你能想到的人物，他们过去和现在都在玩一场地位游戏。</p><p>否则他们怎么可能获得如此大规模的关注，吸引一层层的追随者，并朝更好的方向改变演化的进程？我不想听你举那些高地位人物忽视内在修行和个人成长、以此来平衡地位所带来的混乱这种特例。</p><p>换句话说，如果你想在足够大的规模上为人类做出贡献，地位就是<em>重要的</em>。</p><p>如果一件事与地位无关，它注定会消亡。</p><p>地位是刻在我们这个物种生存本能中的东西，一旦这一点变得有意识，你就能影响世界，并将你追逐地位所带来的负面效应降到最低。</p><p>如果它仍处于无意识状态，你就会在不知不觉中操纵和欺骗他人。</p><p>你可以整天给我看“意识等级表”的图片，试图说服我关于自我消融的道理，但那个等级表本身仍然是一个由不同地位构成的层级体系，是对意识状态混合复杂性的一种静态呈现，而你依然是在说服我某种东西比另一种东西更好。</p><p>地位并不是一个静态的、邪恶的构造。它有高低之分。但没有人一开始就站在顶端。</p><h2 id="价值方程式-如何让任何事物变得有价值" tabindex="-1">价值方程式：如何让任何事物变得有价值 <a class="header-anchor" href="#价值方程式-如何让任何事物变得有价值" aria-label="Permalink to &quot;价值方程式：如何让任何事物变得有价值&quot;">​</a></h2><blockquote><p>解决问题者，或者说价值创造者的道路，正是你逃离“可被替代”世界的方式。热爱问题所带来的挑战，无论是表面的还是形而上的，你理想中的未来就会自行创造出来。——《专注的艺术》</p></blockquote><p>外表先于深度。</p><p>一辆漂亮的车能让一位身价十亿的创始人主动接近你，问你是做什么的，从而为你打开一个充满机会的世界。</p><p>一个健美的身材能让你在一个看重健康、力量与自律的伴侣面前打开机会之门。</p><p>人们喜欢对物质或表面的追求关闭心门，却没意识到那些恰恰是唯一的起点。你不会从核心开始挖掘。你是从表面开始挖的。物质是通往非物质的屏障。</p><p>变得有价值，也就是同时提升外表和深度的影响力，正是你玩转人生游戏的方式。</p><p>不要厌恶这个游戏。不要厌恶玩家。把两者都精通。</p><p>就我而言，地位其实就是你在人生这场游戏中的经验等级。</p><h3 id="价值的宏量营养素——视角" tabindex="-1">价值的宏量营养素——视角 <a class="header-anchor" href="#价值的宏量营养素——视角" aria-label="Permalink to &quot;价值的宏量营养素——视角&quot;">​</a></h3><p>当你理解如何创造价值时，你就能：</p><ul><li>改变自己的人生</li><li>帮助他人改变他们的人生</li><li>清晰地写作、说话与思考</li><li>创作出能带来销售的内容、落地页或营销文案</li><li>以互利的方式经营人际关系</li><li>理解你的情绪并超越它们</li></ul><p>我即将教给你的框架，就是你如何为问题创造解决方案的方法。</p><p>它是人类行为、商业和沟通的基础。</p><p>价值就是真相。</p><p>价值就是故事。</p><p>价值就是进步。</p><p>价值就是转变。</p><p>价值就是逆转熵增。</p><p>价值是你心理层面上意义的信号。</p><p>我们的大脑里有一些小小的想法在漂浮，等待被连接起来。</p><p>当它们连接起来时，你会感受到那种清晰感。一切都豁然开朗。</p><p>每当你未能实现某个结果——比如赚更多钱、改善健康，或激励自己去为更好的未来行动——那是因为你缺少了让一切拼合起来的某个环节：</p><ul><li><strong>问题</strong>——一种未被解决时会带来痛苦的限制或挑战。</li><li><strong>目标</strong>——一个能让接收者超越问题、实现进化的、有影响力的最终结果。</li><li><strong>过程</strong>——一套能培育知识、技能与觉知的创造性系统，用以弥合问题与解决方案之间的差距。</li></ul><p>如果你想改善自己的人生，你必须识别出一个问题，把心智引向一个目标，并不断试验各种解决方案，直到你找到一条通往实现目标的路径。</p><p>如果你想赚钱，你必须帮助他人识别出一个问题，把他们的注意力引向一个目标，并给予他们为更美好的未来采取行动所需的清晰感。</p><p>如果你想改善一段关系，你们双方都必须意识到问题所在，在脑中共同拥有一个目标，并都为解决这个问题付出努力。</p><p>问题、目标和过程，为你所做的一切事情提供了结构——从写作到营销、到行为举止、到打造产品，再到讲述一个故事。</p><p>如果你读过<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》</a>，你之前已经见过这个内容，它就是“目的、路径、优先级”那一章。</p><p>现在，如果你想让这个更具影响力，就要利用价值的微量营养素。</p><h3 id="价值的微量营养素——感知" tabindex="-1">价值的微量营养素——感知 <a class="header-anchor" href="#价值的微量营养素——感知" aria-label="Permalink to &quot;价值的微量营养素——感知&quot;">​</a></h3><p>价值归结为视角与感知。</p><p>如果人们没有意识到问题存在，不相信目标是可实现的，或者缺乏实现目标所需的清晰感——他们就无法感知到你所提供价值的重要性。</p><p>用以下这些方式来塑造读者的感知：</p><ul><li><strong>概念</strong>——一种打包并命名你的价值的方式，能吸引注意力并牢牢印在人们脑中。</li><li><strong>证明</strong>——通过个人或同类结果，让人们相信这是可能实现的。</li><li><strong>风险逆转</strong>——降低人们对获得结果所感知到的不确定性、阻力和难度。</li><li><strong>痛点</strong>——放大问题，说明这个问题在表面之下如何影响着他们的生活。</li><li><strong>好处</strong>——增强达成解决方案的渴望，如果这些好处不断被重复提及，就能让动力持续下去。</li><li><strong>意识水平</strong>——受该问题困扰、能从解决方案中获益、并已准备好接受清晰指引去行动的人数。</li></ul><p>如果我想卖一个新产品来赚取创意收入，下面是我会如何进行拆解规划的方式。</p><ul><li><strong>问题</strong>——我讨厌长时间工作。</li><li><strong>目标</strong>——每天只工作4小时。</li><li><strong>过程</strong>——创办一家企业，学习所需技能，专注于高杠杆任务（你可以并且应该在这方面深入细化）。</li></ul><p>这帮助我构建我所写内容的框架，帮助他人也采纳同样的视角。</p><p>以上所有内容都可以用作单条社交媒体帖子、新闻邮件或视频脚本的大纲，以及任何其他需要你展示价值的场合。</p><p><strong>概念</strong></p><p><em>例子：每天工作4小时。</em></p><p>当你为一个概念命名，比如“艾森豪威尔矩阵”或“每天进步1%”，你就增加了让人们记住你的可能性。</p><p>我使用像“一人企业”或“价值方程式”（正如本文）这样的概念，为一个乏味的话题带来一种能改变人们生活的新颖视角。</p><p>这对标题、视频名称，或吸引注意力的钩子都非常有效。</p><p><strong>证明</strong></p><p><em>例子：我帮约翰·史密斯（John Smith）理清了任务优先级，让他工作更少、收入更多。</em></p><p>在我的新闻邮件里，我常常从一个基于我个人经历的问题开始，讲述我是如何克服它的。这让人们相信、并觉得自己也能做到这一点。</p><p>尽你所能地使用一切素材——统计数据、客户故事，或个人经历——来展示什么是可能实现的。</p><p><strong>风险逆转</strong></p><p><em>例子：你每天只需要10分钟就能开始。</em></p><p>人们需要的是清晰感，而不是动力。你要如何降低人们所感知到的做出改变的风险和阻力？</p><p>在营销中，人们使用退款保证。</p><p>在写作中，我尝试把事情讲得极其简单明了，让人们没有理由继续平庸下去。</p><p>我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《两小时写作者》</a>中教你如何写作以打造受众（从而将你的价值变现分发）。</p><p><strong>痛点</strong></p><p><em>例子：你没有时间陪伴家人。你没有时间追求其他目标。你没有值得专注的有意义的工作。</em></p><p>在我的落地页上，我会以一份痛点清单开头，让人们意识到他们问题所带来的影响。这打开了一个好奇心循环，让他们的大脑渴望一个解决方案。</p><p>记住，我给出的例子只是众多方式中的一种。所有这些都应被视为你创作时的创意火力。</p><p><strong>好处</strong></p><p><em>例子：选择你想工作的时间。选择你想做的工作。选择你想合作的人。</em></p><p>这里有一个我可能会用“好处”写出的社交媒体帖子示例。这正是大多数人应该开始写的内容，以在他们所选择的话题中建立权威：</p><blockquote><p>你创业是因为你想要：</p><ul><li>选择你何时工作</li><li>选择你做什么工作</li><li>选择你和谁一起工作</li></ul><p>别忘了：创业并不是关于长时间工作。</p><p>而是关于掌控你的时间、金钱和乐趣。</p></blockquote><p>（我现在正把这个安排成一条帖子发出去，去我的主页看看效果如何。注意其中隐含着一个问题、一个目标和一个过程，人们如果关注我，就会逐渐了解这些。）</p><p>这可以作为销售页、新闻邮件的一部分，或用作一条社交媒体帖子，为读者预先铺垫你的价值。</p><p><strong>意识水平</strong></p><p>意识水平共有5个层级：</p><ul><li>第1级：未意识到问题。</li><li>第2级：意识到问题。</li><li>第3级：意识到解决方案。</li><li>第4级：意识到产品。</li><li>第5级：最高意识水平。</li></ul><p>大多数人会处于第1到第4级之间。</p><p>你的工作，是在你的个人简介、内容、网站、邮件、私信、通话等各个阶段，针对每一层级说出对应的话，直到他们意识到你的产品（或价值）正是他们需要落实的东西。</p><p>如果某人处于第2级（意识到问题），以下是我会针对“每天工作4小时”这个概念写的一个示例帖子：</p><blockquote><p>如果你讨厌长时间工作：</p><ul><li>增加你的技能储备</li><li>终于开始创业</li><li>每天投入1小时去做</li><li>把老板从你的生活中开除</li><li>随心所欲地工作</li></ul><p>如果你不创造出属于自己的工作方式，你永远不会少工作。</p></blockquote><p>注意我是如何用“过程”来给他们提供问题的解决方案的。</p><p>利用价值方程式，去填补你思维、事业和人生中的空白。</p><p>如果你想获得个性化指导，用12到16周的时间成为一名综合者（或价值创造者），并以此为职业，请申请加入<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex 大学</a>。</p><h2 id="顶尖1-人群的生活方式" tabindex="-1">顶尖1%人群的生活方式 <a class="header-anchor" href="#顶尖1-人群的生活方式" aria-label="Permalink to &quot;顶尖1%人群的生活方式&quot;">​</a></h2><p>所有高价值个体都拥有一种共同的生活方式。</p><p>他们每天都在逆转熵增。</p><p>他们每天都在追求目标。</p><p>他们每天都在解决问题。</p><p>他们每天都在提出假设、进行测试，并创造出可以分发给他人的解决方案。</p><p>这种生活方式要求持续不断地学习、构建和分发价值。</p><p>价值就是逆转熵增。</p><p>熵增就是向混乱的堕落。</p><p>通过创建系统、解决问题来实现目标，从而逆转熵增。这就是价值方程。</p><p>有一种职业永远不会过时：按照自然法则去赚钱。也就是说，通过不断解决层出不穷的问题来逆转熵增，把解决方案转化为潜在利润，并把你创造的价值分发给他人。</p><p>无论经济走向何方，无论AGI（通用人工智能）取代了多少工作岗位，无论你有多担心……因为那种担忧本身，也只是别人同样在承受的一个问题——你可以为所有相关方解决它，并通过教育类和意义类的内容与产品，从中获得丰厚的利润。</p><p>没有人会把时间给你，你必须自己去争取。</p><p>从每天早晨、在各种干扰苏醒之前的那1个小时开始。</p><p>解决你生活中的一个问题，让它孕育出一个能盈利的解决方案。</p><p>通过写作和内容分发你的价值，从而积累受众。</p><p>把你的解决方案变成一个产品，不断迭代，直到赚到你想要的收入为止。</p><p>不要靠一份薪水来维持你的生存。</p><p>通过创业超越生存的束缚，把你人生中赚钱的上限彻底移除。</p><p>最后，祝你享受这周剩下的时光。</p><p>丹（Dan）</p><hr><p><a href="/en/letters/the-value-equation-how-to-become-a-top-1-individual-fast">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',117))])}const v=o(c,[["render",h]]);export{q as __pageData,v as default};
